'use client';
import {useState} from 'react';
export default function ImprimirOrcamento(){const [vat,setVat]=useState(23);const subtotal=12500;const iva=subtotal*vat/100;return <main style={{padding:40,fontFamily:'Arial',maxWidth:900,margin:'auto'}}><div style={{display:'flex',justifyContent:'space-between'}}><div><h1>ROYAL EPOXI</h1><p>Orçamento RE-2026-027</p></div><button onClick={()=>window.print()}>Imprimir / Guardar PDF</button></div><hr/><h2>Cliente</h2><p>Nome do cliente<br/>NIF · Morada · Telefone</p><h2>Trabalhos</h2><table style={{width:'100%',borderCollapse:'collapse'}}><tbody><tr><td style={{padding:10,borderBottom:'1px solid #ddd'}}>Preparação e aplicação de sistema epóxi</td><td style={{padding:10,textAlign:'right'}}>€12.500,00</td></tr></tbody></table><div style={{marginTop:30,textAlign:'right'}}><p>Subtotal: €{subtotal.toFixed(2)}</p><label>IVA <input type="number" value={vat} onChange={e=>setVat(+e.target.value)} style={{width:70}}/>%</label><h2>Total: €{(subtotal+iva).toFixed(2)}</h2></div><h3>Condições</h3><p>Validade do orçamento, condições de pagamento, prazo previsto e exclusões serão apresentados aqui.</p></main>}
